importScripts('geometry.js','rectifier-core.js');
self.onmessage=async({data})=>{const{bitmap,outer}=data;let output,tileCanvas;const tiles=new Map();try{const{width,height,r}=CenterRectifier.outputSize(outer);output=new OffscreenCanvas(width,height);const ctx=output.getContext('2d');tileCanvas=new OffscreenCanvas(256,256);const tc=tileCanvas.getContext('2d',{willReadFrequently:true}),W=bitmap.width,H=bitmap.height;
function tileAt(x,y){const tx=Math.floor(x/256)*256,ty=Math.floor(y/256)*256,key=tx+','+ty;let tile=tiles.get(key);if(!tile){const tw=Math.min(256,W-tx),th=Math.min(256,H-ty);tc.clearRect(0,0,256,256);tc.drawImage(bitmap,tx,ty,tw,th,0,0,tw,th);tile={data:tc.getImageData(0,0,tw,th).data,width:tw,tx,ty};tiles.set(key,tile);if(tiles.size>96)tiles.delete(tiles.keys().next().value);}return tile;}
function sample(x,y,out,k){const ix=Math.floor(x),iy=Math.floor(y),fx=x-ix,fy=y-iy;if(ix>=0&&iy>=0&&ix+1<W&&iy+1<H&&Math.floor(ix/256)===Math.floor((ix+1)/256)&&Math.floor(iy/256)===Math.floor((iy+1)/256)){const tile=tileAt(ix,iy),p=((iy-tile.ty)*tile.width+ix-tile.tx)*4,idx=[p,p+4,p+tile.width*4,p+tile.width*4+4],weights=[(1-fx)*(1-fy),fx*(1-fy),(1-fx)*fy,fx*fy];let alpha=0,rr=0,gg=0,bb=0;for(let j=0;j<4;j++){const at=idx[j],a=tile.data[at+3]*weights[j];alpha+=a;rr+=tile.data[at]*a;gg+=tile.data[at+1]*a;bb+=tile.data[at+2]*a;}out[k]=alpha?rr/alpha:0;out[k+1]=alpha?gg/alpha:0;out[k+2]=alpha?bb/alpha:0;out[k+3]=alpha;return;}CenterRectifier.bilinear((px,py)=>{if(px<0||py<0||px>=W||py>=H)return[0,0,0,0];const tile=tileAt(px,py),i=((py-tile.ty)*tile.width+px-tile.tx)*4;return tile.data.subarray(i,i+4);},x,y,out,k);}
for(let y=0;y<height;y+=32){const rows=Math.min(32,height-y),image=ctx.createImageData(width,rows);CenterRectifier.warpStrip(r,width,height,y,rows,sample,image.data);ctx.putImageData(image,0,y);self.postMessage({progress:Math.round((y+rows)/height*95),label:'按原图精度校正与裁切'});}self.postMessage({progress:97,label:'编码无标记 PNG'});const blob=await output.convertToBlob({type:'image/png'});self.postMessage({result:{blob,width,height}});
}catch(e){self.postMessage({error:'校正图导出失败：'+(e.message||'可能超出浏览器画布或内存限制')+'。不会自动缩小原图。'});}finally{tiles.clear();bitmap?.close();if(output)output.width=output.height=1;if(tileCanvas)tileCanvas.width=tileCanvas.height=1;}};
